'use client';

import React from 'react';
import * as THREE from 'three';

export interface PlantItem {
  id: string;
  name: string;
  modelPath?: string;
  position: [number, number, number];
  scale?: [number, number, number];
}

interface PlantFieldProps {
  tankBounds: THREE.Vector3;
  plantsConfig?: PlantItem[];
}

export default function PlantField({
  tankBounds,
  plantsConfig = [],
}: PlantFieldProps) {
  // İleride bitkiler ve dekoratif objeler (kaya, ağaç kökü vb.) buraya dinamik eklenecek
  return (
    <group name="plant-field">
      {plantsConfig.map((plant) => (
        <group
          key={plant.id}
          position={plant.position}
          scale={plant.scale || [1, 1, 1]}
        >
          {/* Bitki 3D GLTF modeli buraya entegre edilecek */}
        </group>
      ))}
    </group>
  );
}
